from PIL import Image
img = Image.open('/app/chess_board.png').convert('RGB')
LIGHT=(240,217,181); DARK=(181,136,99)
files='abcdefgh'; rows='87654321'
data=img.load()
def isbg(p):
    R,G,B=p
    return (abs(R-LIGHT[0])<35 and abs(G-LIGHT[1])<35 and abs(B-LIGHT[2])<35) or \
           (abs(R-DARK[0])<35 and abs(G-DARK[1])<35 and abs(B-DARK[2])<35)
pieces = {
 'a8':'B','c8':'B','d8':'B','f8':'B','b7':'B','f7':'B','g7':'B','a6':'B','c6':'B','e6':'B','d5':'B','f5':'B','g5':'B',
 'e5':'W','h5':'W','a3':'W','c3':'W','b2':'W','e2':'W','f2':'W','g2':'W','a1':'W','c1':'W','e1':'W','h1':'W',
}
def getmask(name, n=16):
    col=files.index(name[0]); row=rows.index(name[1])
    x0,y0=col*80,row*80
    sub=img.crop((x0,y0,x0+80,y0+80)).resize((n,n))
    px=sub.load()
    m=[]
    for y in range(n):
        rowb=[]
        for x in range(n):
            rowb.append(0 if isbg(px[x,y]) else 1)
        m.append(rowb)
    return m
def sim(a,b):
    inter=un=0
    for i in range(16):
        for j in range(16):
            if a[i][j] or b[i][j]: un+=1
            if a[i][j] and b[i][j]: inter+=1
    return inter/un if un else 0
masks={n:getmask(n) for n in pieces}
# cluster
clusters=[]
assigned={}
for n in pieces:
    placed=False
    for c in clusters:
        if sim(masks[n], masks[c[0]])>0.75:
            c.append(n); placed=True; break
    if not placed:
        clusters.append([n])
for i,c in enumerate(clusters):
    col=pieces[c[0]]
    print(f'Cluster {i} ({"B" if col=="B" else "W"}-ref {c[0]}): {c}')
